package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetParent;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The rates a sheet's figures use: its own, then, for a grade and date it has none in force on, its
 * parent's, its parent's parent's, up to {@link SheetParent#LEVELS} levels up.
 */
@Service
public class InheritedRates {

    private final RateRepository rates;
    private final RateLogRepository log;
    private final SheetParentRepository parents;

    public InheritedRates(RateRepository rates, RateLogRepository log, SheetParentRepository parents) {
        this.rates = rates;
        this.log = log;
        this.parents = parents;
    }

    /** The sheet's rates and its ancestors', as they are now. */
    @Transactional(readOnly = true)
    public RateLevels of(String sheetId) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        levels.add(byGrade(rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)));
        levels.addAll(ancestors(sheetId));
        return new RateLevels(levels);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade, as they are now. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestors(String sheetId) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        for (String ancestor : parents.ancestorsOf(sheetId, SheetParent.LEVELS)) {
            levels.add(byGrade(rates.findBySheetIdOrderByGradeAscFromDateAsc(ancestor)));
        }
        return levels;
    }

    /** The sheet's rates and its ancestors', each as they stood at the end of the date ({@link #asOf(String, LocalDate)}). */
    @Transactional(readOnly = true)
    public RateLevels levelsAsOf(String sheetId, LocalDate date) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        levels.add(asOf(sheetId, date));
        levels.addAll(ancestorsAsOf(sheetId, date));
        return new RateLevels(levels);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade as they stood at the end of the date. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestorsAsOf(String sheetId, LocalDate date) {
        List<Map<String, List<Rate>>> levels = new ArrayList<>();
        for (String ancestor : parents.ancestorsOf(sheetId, SheetParent.LEVELS)) levels.add(asOf(ancestor, date));
        return levels;
    }

    /**
     * A sheet's rates by grade as they stood at the end of the date: of those set while its today was
     * on or before it, the last set for each grade and from-date (its newest version then).
     */
    @Transactional(readOnly = true)
    public Map<String, List<Rate>> asOf(String sheetId, LocalDate date) {
        Map<String, Map<Optional<LocalDate>, Rate>> then = new LinkedHashMap<>();
        for (RateLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
            if (!line.setBy(date)) continue;
            Map<Optional<LocalDate>, Rate> grade = then.computeIfAbsent(line.getGrade(), g -> new LinkedHashMap<>());
            Optional<LocalDate> from = Optional.ofNullable(line.getFromDate());
            Rate replaced = grade.get(from);
            grade.put(from, line.toRate(replaced == null ? 1 : replaced.getVersions() + 1));
        }
        Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
        then.forEach((grade, rates) -> byGrade.put(grade, new ArrayList<>(rates.values())));
        return byGrade;
    }

    private static Map<String, List<Rate>> byGrade(List<Rate> list) {
        Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
        for (Rate rate : list) byGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        return byGrade;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.AsOfGuard;
import net.officefloor.hq.app.claim.ClaimService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it, with its version count; the percent always has two decimals; from is null from the start, to null with no end. */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct, int versions) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFromDate(), rate.getToDate(), rate.getPct().setScale(2).toPlainString(),
                    rate.getVersions());
        }
    }

    /** A percent of 0.00 or more, with at most two decimals, from a date (none: from the beginning of time) through a date (none: no end). */
    public record RateRequest(@NotNull @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String pct, LocalDate from, LocalDate to) {

        BigDecimal pctValue() {
            return new BigDecimal(pct).setScale(2);
        }
    }

    /** Pasted lines of grade,rate,from,to, one rate each. */
    public record ImportRequest(@NotNull @Size(max = 200000) String text) {}

    /** How many rates an import set, and each as the store now holds it, in the order of their lines. */
    public record ImportView(int set, List<RateView> rates) {}

    /** A rate preview as the screen shows it: how many claims' dues would change, and the sum of the differences (two decimals). */
    public record PreviewView(int count, String diff) {}

    private final RateService service;
    private final ClaimService claims;
    private final RateImportService importer;

    public RateController(RateService service, ClaimService claims, RateImportService importer) {
        this.service = service;
        this.claims = claims;
        this.importer = importer;
    }

    /** What the percent as the grade's rate on every date would change; nothing is stored. */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestParam @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String pct) {
        ClaimService.RatePreview preview = claims.previewRate(sheetId, grade, new BigDecimal(pct).setScale(2));
        return new PreviewView(preview.count(), preview.diff().setScale(2).toPlainString());
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    /**
     * The rates of the sheet's ancestors, nearest first (up to three levels up), that a grade with no rate
     * of its own in force on a date takes; as of the user's as-of date, each as it stood at the end of it.
     */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String asOf) {
        LocalDate date = asOf == null || asOf.isBlank() ? null : LocalDate.parse(asOf.strip());
        return service.ancestors(sheetId, date).stream()
                .map(level -> level.values().stream().flatMap(List::stream).map(RateView::of).toList())
                .toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId, user, grade, request.from(), request.to(), request.pctValue()));
    }

    /** Set a rate per pasted line, in order, each as the form sets it; a line refused refuses them all. */
    @PostMapping("/import")
    public ImportView importRates(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ImportRequest request) {
        List<RateView> set = importer.importRates(sheetId, user, request.text()).stream().map(RateView::of).toList();
        return new ImportView(set.size(), set);
    }
}
