package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Imported rates: lines of grade,rate,from,to (the last two may be absent or blank), each checked
 * first with the rate form's rules, then set in order exactly as the form sets one (replacing a rate
 * for the same grade and from-date). Blank lines are skipped; a paste with no line is refused. It is
 * one change: a line that is refused refuses them all.
 */
@Service
public class RateImportService {

    private static final Pattern GRADE = Pattern.compile("[ABC]");
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");
    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");

    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {}

    private final RateService rates;

    public RateImportService(RateService rates) {
        this.rates = rates;
    }

    /** The rates set, in the order of their lines. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        for (String raw : text.split("\\R")) {
            if (raw.isBlank()) continue;
            lines.add(parse(raw));
        }
        if (lines.isEmpty()) throw new RateImportRefusedException();
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) {
            set.add(rates.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        }
        return set;
    }

    private Line parse(String raw) {
        String[] fields = raw.split(",", -1);
        if (fields.length < 2 || fields.length > 4) throw new RateImportRefusedException();
        String grade = fields[0].strip();
        String pct = fields[1].strip();
        LocalDate from = date(fields.length > 2 ? fields[2].strip() : "");
        LocalDate to = date(fields.length > 3 ? fields[3].strip() : "");
        if (!GRADE.matcher(grade).matches() || !PCT.matcher(pct).matches()) throw new RateImportRefusedException();
        if (from != null && to != null && to.isBefore(from)) throw new RateImportRefusedException();
        return new Line(grade, new BigDecimal(pct).setScale(2), from, to);
    }

    /** A yyyy-mm-dd date, or null when blank. */
    private static LocalDate date(String text) {
        if (text.isEmpty()) return null;
        if (!DATE.matcher(text).matches()) throw new RateImportRefusedException();
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new RateImportRefusedException();
        }
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.Comparator;
import java.util.Optional;

/**
 * The sheet's rate for one grade from a date: a percent with two decimals (0.00 or more). A rate
 * with no from-date applies from the beginning of time; one with a to-date applies through it. Setting
 * a grade and from-date again adds a new version; the row holds the newest, the one in force.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "versions", nullable = false)
    private int versions = 1;

    protected Rate() {}

    public Rate(String sheetId, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.pct = pct;
    }

    /** The rate as it stood after the given number of versions. */
    public Rate(String sheetId, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct, int versions) {
        this(sheetId, grade, fromDate, toDate, pct);
        this.versions = versions;
    }

    /**
     * Of one grade's rates, the one in force on the date: the one with the latest from-date on or
     * before it, unless the date is after that rate's to-date (then none).
     */
    public static Optional<Rate> inForce(Collection<Rate> rates, LocalDate date) {
        return rates.stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> rate.toDate == null || !date.isAfter(rate.toDate));
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getGrade() { return grade; }

    /** The first date it applies on; null when it applies from the beginning of time. */
    public LocalDate getFromDate() { return fromDate; }

    /** Whether it applies on the date: it has no from-date, or one on or before the date. */
    public boolean appliesOn(LocalDate date) { return fromDate == null || !fromDate.isAfter(date); }

    /** The last date it applies on; null when it has no end. */
    public LocalDate getToDate() { return toDate; }

    public BigDecimal getPct() { return pct; }

    /** How many times its grade and from-date have been set; this is the newest version, the older ones are in the rate log. */
    public int getVersions() { return versions; }

    /** Keep the current value as an older version and make the percent and to-date the newest one. */
    public void addVersion(BigDecimal pct, LocalDate toDate) {
        this.versions++;
        this.pct = pct;
        this.toDate = toDate;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * A sheet's rates by grade, then those of each of its ancestors, nearest first (see
 * {@link net.officefloor.hq.app.sheet.SheetParent}): a grade's rate on a date is the sheet's own in
 * force then, else the nearest ancestor's in force then.
 */
public record RateLevels(List<Map<String, List<Rate>>> levels) {

    /** The grade's rate on the date: the first level's that has one in force then. */
    public Optional<Rate> inForce(String grade, LocalDate date) {
        for (Map<String, List<Rate>> level : levels) {
            Optional<Rate> rate = Rate.inForce(level.getOrDefault(grade, List.of()), date);
            if (rate.isPresent()) return rate;
        }
        return Optional.empty();
    }
}
